/*
 * The learner's own programme, at the SERVER's clock (§0.6). `now` is not a
 * parameter of this function at all, so a learner cannot move the clock that
 * decides what `state` says about them. '' means "the server clock".
 */
if (Inputs.learnerId !== undefined) {
  Outputs.query = { learnerId: String(Inputs.learnerId), now: '' };
}

/*
 * WHAT THE LEARNER MAY READ — `projectForLearner` (src/lib/server/timeline/model.ts).
 *
 * A SEPARATE NODE FROM THE COACH'S, NEVER A FLAG (L91, L116). Three things
 * leave the superset here and nowhere else:
 *   - every `signal` — our inference about their confusion, never theirs to be
 *     shown back (L60's self-certification from the other direction);
 *   - every INTERNAL note — a coach's private working note (L128). In the
 *     product these never reach the learner's assembly at all; here the
 *     superset carries them, so this filter is the whole boundary;
 *   - `history` — the learner's page does not read it (L170 §1).
 * And `unread` is resolved from the learner's side.
 */
if (Inputs.payload !== undefined) {
  try {
    const p = Inputs.payload;
    const resolveUnread = (e) => (e.kind === 'message' ? { ...e, unread: e.authorRole !== 'learner' && !e.read } : e);
    const stripNote = (e) => {
      if (e.kind !== 'note') return e;
      const { _visibility, ...note } = e.note;
      return { ...e, note };
    };
    const entries = p.entries
      .filter((e) => e.kind !== 'signal')
      .filter((e) => e.kind !== 'note' || e.note._visibility === 'shared')
      .map(stripNote)
      .map(resolveUnread);
    const { history, ...rest } = p;
    Outputs.rows = [{ ...rest, entries }];
    Outputs.done();
  } catch (e) {
    Outputs.error = String((e && e.message) || e);
    // Logged for the operator; the caller still gets one refusal body (the mcp/auth.ts rule).
    console.error('[dbt:course]', Outputs.error);
    Outputs.failed();
  }
}
